                        .orElse(null);
                if (last != null && SEAL_STATUS_SEALED.equals(last.status())) {
                    // 理论上活跃表与事件表一致，出现不一致以 409 保护
                    throw ApiException.conflict("封箱键已有未作废版本: " + box.sealKey());
                }
                if (activeByLabel.containsKey(box.labelNo())) {
                    throw ApiException.unprocessable("标签号已被本批次其他封箱占用: " + box.labelNo());
