/**
 * 登记包装计划：计划数量为正整数，号段 [start,end] 两端含且容量不得小于计划数量。
 * 每个批次至多登记一次，重复登记返回 409；批次不存在返回 404；已召回批次禁止登记返回 409。
 */
public StoredResponse registerPacking(String batchKey, RegisterPackingRequest req) {
    if (req.labelRangeEnd() < req.labelRangeStart()) {
        throw ApiException.badRequest("labelRangeEnd 不得小于 labelRangeStart");
    }
    if (req.labelRangeEnd() - req.labelRangeStart() + 1 < req.plannedQuantity()) {
        throw ApiException.unprocessable("标签号段容量小于计划数量，无法一标签一封箱完成全部计划: "
                + "要求号段容量 " + req.plannedQuantity()
                + "，实际容量 " + (req.labelRangeEnd() - req.labelRangeStart() + 1));
    }

